66	    json intent = intent_section_result(request.intent);
67	    intent["setupTitle"] = request.setup_title;
68	    for (json& field : intent["fields"])
69	        field.erase("updatedAt");
70	    drop_empty(intent);
71	    if (!intent.empty())
72	        result["intent"] = std::move(intent);
73	    const json full_plan = plan_section_result(request.plan);
74	    json plan{{"headline", full_plan["headline"]}, {"decisions", full_plan["decisions"]},
75	              {"assumptions", full_plan["assumptions"]}, {"truncated", full_plan["truncated"]}};
76	    drop_empty(plan);
77	    if (!plan.empty())
78	        result["plan"] = std::move(plan);
79	    return result;
80	}
81	
82	// The app's data beside the person's words, in a tag of its own. JSON keeps
83	// "<" only inside strings, where "<\/" means the same thing, so a project
84	// name cannot close the tag early.
85	std::string tagged(const char* tag, const std::string& json_text)
86	{
87	    std::string escaped;
88	    escaped.reserve(json_text.size());
89	    for (std::size_t i = 0; i < json_text.size(); ++i) {
90	        escaped += json_text[i];
91	        if (json_text[i] == '<' && i + 1 < json_text.size() && json_text[i + 1] == '/')
92	            escaped += '\\';
93	    }
94	    return std::string("<") + tag + ">\n" + escaped + "\n</" + tag + ">";
95	}
96	
97	json text_part(std::string text) { return json{{"type", "input_text"}, {"text", std::move(text)}}; }
98	
99	bool available_in_app(const ToolDefinition& definition, bool allow_import, const std::vector<std::string>& session_tools)
100	{
101	    // A session with a subject of its own offers exactly the tools it names,
102	    // and those may be its own rather than the app's.
103	    if (!session_tools.empty())
104	        return std::find(session_tools.begin(), session_tools.end(), definition.name) != session_tools.end() &&
105	               (has_exposure(definition.exposure, ToolExposure::InApp) || has_exposure(definition.exposure, ToolExposure::Printer));
106	    return has_exposure(definition.exposure, ToolExposure::InApp) &&
107	           (definition.availability == ToolAvailability::Always || allow_import);
108	}
109	
110	bool has_closed_required_objects(const json& schema)
111	{
112	    if (schema.value("type", json()) == "object") {
113	        if (schema.value("additionalProperties", json()) != false)
114	            return false;
115	        const auto properties = schema.value("properties", json::object());
116	        const auto required = schema.value("required", json::array());
117	        for (const auto& property : properties.items())
118	            if (std::find(required.begin(), required.end(), property.key()) == required.end() ||
119	                !has_closed_required_objects(property.value()))
120	                return false;
121	    }
122	    return !schema.contains("items") || has_closed_required_objects(schema["items"]);
123	}
124	
125	json tools_for(bool allow_import, const std::vector<std::string>& session_tools)
126	{
127	    json tools = json::array();
128	    for (const ToolDefinition& definition : ToolRegistry::instance().definitions()) {
129	        if (!available_in_app(definition, allow_import, session_tools))
130	            continue;
131	        tools.push_back(json{{"type", "function"},
132	                             {"name", definition.name},
133	                             {"description", definition.description},
134	                             // OpenAI strict mode cannot express optional
135	                             // fields or dynamic maps. Preserve the registry
136	                             // schema; native validation still owns acceptance.
137	                             {"strict", has_closed_required_objects(definition.input_schema)},
138	                             {"parameters", definition.input_schema}});
139	    }
140	    return tools;
141	}
