66	// Responses API adapter. Network callbacks only append protected input; all
67	// parsing and AgentEvent delivery happens from poll() on the GUI thread.
68	class OpenAIResponsesAgent final : public IAgentService
69	{
70	public:
71	    OpenAIResponsesAgent(OpenAIResponsesConfig config, std::unique_ptr<IAgentHttpTransport> transport);
72	    ~OpenAIResponsesAgent() override;
73	
74	    bool ready() const override;
75	    bool busy() const override;
76	    bool start(const AgentRequest& request) override;
77	    bool continue_after_tool(const AgentToolResult& result) override;
78	    void cancel() override;
79	    std::optional<AgentEvent> poll() override;
80	
81	private:
82	    struct QueuedHttpEvent
83	    {
84	        std::uint64_t generation{0};
85	        AgentHttpEvent event;
86	    };
