2334	bool AgentHost::remember_setup_intent(const ToolActivity& activity)
2335	{
2336	    const json arguments = json::parse(activity.arguments_json, nullptr, false);
2337	    const char* key = "setupTitle";
2338	    if (arguments.is_discarded() || !arguments.is_object() || !arguments.contains(key) ||
2339	        !arguments[key].is_string())
2340	        return false;
2341	    // A change made outside a chat -- an MCP client, say -- has no chat to be
2342	    // the record of, so it leaves no intent behind.
2343	    const std::string conversation_id = m_persistence.document().conversation_of_message(activity.correlation_id);
2344	    if (conversation_id.empty())
2345	        return false;
2346	    if (!m_persistence.document().set_setup_intent(conversation_id, arguments[key].get<std::string>()))
2347	        return false;
2348	    m_persistence.commit();
2349	    // An intent written on a chat you are not looking at changes nothing on
2350	    // screen, so it is not worth a push of its own.
2351	    return conversation_id == m_persistence.document().active_conversation_id();
2352	}
