2354	bool AgentHost::remember_agent_authored(const ToolActivity& activity)
2355	{
2356	    const json result = json::parse(activity.result_json, nullptr, false);
2357	    // A patch that changed nothing wrote nothing, so it authored nothing.
2358	    if (result.is_discarded() || !result.is_object() || !result.value("applied", false) ||
2359	        result.value("scope", "").empty())
2360	        return false;
2361	    const std::string scope = result.value("scope", "");
2362	    const auto changes = result.find("changes");
2363	    if (changes == result.end() || !changes->is_array())
2364	        return false;
2365	    // Both the requested changes and the dependencies Orca normalized as a
2366	    // consequence: the reader did not type either of them. The requested ones
2367	    // are serialized first, so the tool result's 64-entry cap can only ever
2368	    // cost us a dependency, never a setting the agent was asked for.
2369	    for (const json& change : *changes)
2370	        if (change.is_object() && change.contains("key") && change["key"].is_string() &&
2371	            change.contains("after") && change["after"].is_string())
2372	            m_agent_authored[scope + ":" + change["key"].get<std::string>()] = change["after"].get<std::string>();
2373	    return true;
2374	}
