2387	std::set<std::string> AgentHost::agent_authored_keys(const Workspace::WorkspaceSnapshot& snapshot)
2388	{
2389	    // Switching a preset changes the baseline its deltas are measured from, so
2390	    // what the agent wrote against the old one does not carry over. The
2391	    // selected names are read from the setup itself: a preset with nothing
2392	    // edited has no delta to carry its name, and is switched all the same.
2393	    const std::pair<const char*, const std::string&> selected[] = {{"process", snapshot.setup.process_preset},
2394	                                                                   {"filament", snapshot.setup.filament_preset},
2395	                                                                   {"printer", snapshot.setup.printer_preset}};
2396	    for (const auto& [type, name] : selected) {
2397	        const auto bound = m_agent_authored_presets.find(type);
2398	        if (bound == m_agent_authored_presets.end()) {
2399	            m_agent_authored_presets.emplace(type, name);
2400	        } else if (bound->second != name) {
2401	            const std::string prefix = std::string(type) + ":";
2402	            for (auto authored = m_agent_authored.begin(); authored != m_agent_authored.end();)
2403	                if (authored->first.rfind(prefix, 0) == 0) authored = m_agent_authored.erase(authored); else ++authored;
2404	            bound->second = name;
2405	        }
2406	    }
2407	    std::set<std::string> keys;
2408	    for (const Workspace::PresetDelta& delta : snapshot.preset_deltas) {
2409	        const std::string scoped_key = delta.preset_type + ":" + delta.key;
2410	        const auto found = m_agent_authored.find(scoped_key);
2411	        // The agent's only while the value it applied is the value in force.
2412	        // Edit that setting by hand and the delta becomes yours again.
2413	        if (found != m_agent_authored.end() && found->second == delta.value)
2414	            keys.insert(scoped_key);
2415	    }
2416	    return keys;
2417	}
