2435	void AgentHost::continue_after_tool(const ToolActivity& activity)
2436	{
2437	    const auto found = m_tool_continuations.find(activity.action_id);
2438	    if (found == m_tool_continuations.end())
2439	        return;
2440	
2441	    PendingToolContinuation continuation = found->second;
2442	    m_tool_continuations.erase(found);
2443	
2444	    json       output = tool_output_json(activity);
2445	    // A session about something other than the project is never told about
2446	    // the project, in its tool results any more than in its turns.
2447	    if (m_session_profile.include_workspace) {
2448	        const WorkspaceSnapshot current_workspace = m_workspace.snapshot();
2449	        output["actionId"]          = activity.action_id;
2450	        output["workspaceRevision"] = current_workspace.revision;
2451	        output["workspace"]         = context_json(current_workspace, agent_authored_keys(current_workspace));
2452	    }
2453	    AgentToolResult result;
2454	    result.call_id     = continuation.call_id;
2455	    result.state       = tool_state_name(activity.state);
2456	    result.output_json = output.dump();
2457	    result.image       = activity.image;
2458	    if (!m_agent || !m_agent->continue_after_tool(result)) {
2459	        begin_tool_followup(continuation);
2460	        fail_stream(AgentError{"agent_continuation_failed", "The Agent could not receive the native tool result.", true});
2461	        return;
2462	    }
2463	    begin_tool_followup(continuation);
2464	}
