75	// The JSON inside "<tag>\n...\n</tag>", or a discarded value when the text
76	// is not exactly one such block.
77	json tagged_json(const json& part, const std::string& tag)
78	{
79	    const std::string open = "<" + tag + ">\n", close = "\n</" + tag + ">";
80	    if (!part.is_object() || part.value("type", "") != "input_text" || !part.contains("text"))
81	        return json(json::value_t::discarded);
82	    const std::string text = part["text"].get<std::string>();
83	    if (text.size() < open.size() + close.size() || text.rfind(open, 0) != 0 ||
84	        text.compare(text.size() - close.size(), close.size(), close) != 0)
85	        return json(json::value_t::discarded);
86	    return json::parse(text.substr(open.size(), text.size() - open.size() - close.size()), nullptr, false);
87	}
