"""Replace one case of a project prompt recording with the same case from another
recording, keeping the recorder's file-wide settingItems table consistent."""
import json, sys

def dump(v): return json.dumps(v, separators=(",", ":"), sort_keys=True, ensure_ascii=False)

def expand(doc):
    items = doc["settingItems"]
    cases = json.loads(json.dumps(doc["cases"]))
    for case in cases.values():
        for answer in case["answers"]:
            if answer.pop("settingItems", False):
                out = json.loads(answer["output"])
                for f in ("items", "unknownKeys"):
                    if f in out["result"]:
                        out["result"][f] = [items[i] for i in out["result"][f]]
                answer["output"] = dump(out)
    return cases

def compress(cases):
    items, index = [], {}
    for name in sorted(cases):
        for answer in cases[name]["answers"]:
            if answer["tool"] not in ("settings_get", "settings_search"):
                continue
            out = json.loads(answer["output"])
            for f in ("items", "unknownKeys"):
                if f not in out["result"]:
                    continue
                refs = []
                for item in out["result"][f]:
                    key = dump(item)
                    if key not in index:
                        index[key] = len(items); items.append(item)
                    refs.append(index[key])
                out["result"][f] = refs
            answer["output"] = dump(out)
            answer["settingItems"] = True
    return {"settingItems": items, "cases": {name: cases[name] for name in sorted(cases)}}

def write(doc, path):
    open(path, "w", encoding="utf-8").write(json.dumps(doc, indent=1, ensure_ascii=False) + "\n")

if __name__ == "__main__":
    base, donor, case, out = sys.argv[1:5]
    cases = expand(json.load(open(base, encoding="utf-8")))
    if case != "-":
        cases[case] = expand(json.load(open(donor, encoding="utf-8")))[case]
    write(compress(cases), out)
EOF
